function h(t){return[...new Set(t.map(e=>e.trim()).filter(Boolean))]}const c=12;function i(t){let e=0;for(const r of t)e=e*31+r.charCodeAt(0)>>>0;return e}function l(t,e,r){const o=Math.abs(t-e);return Math.min(o,r-o)}function m(t){const r=[...h(t)].sort((s,u)=>{const n=i(s)-i(u);return n!==0?n:s.localeCompare(u)}),o=Array.from({length:c},()=>0),f={};for(const s of r){const u=i(s)%c;let n=0,T=Number.POSITIVE_INFINITY;for(let a=0;a<c;a+=1){const g=o[a]*100+l(u,a,c);g<T&&(T=g,n=a)}o[n]+=1,f[s]=n}return f}function C(t,e){return e&&t in e?e[t]:i(t)%c}export{m as c,C as g,h as s};
